  object-fit: cover;
  flex-shrink: 0;
}
.xt-name {
  flex: 1;
  font-size: 14px; font-weight: 800;
  color: #f5f5f3;
  line-height: 1.5;
}
.xt-text-tweet {
  font-size: 17px; font-weight: 550;
  line-height: 1.8; letter-spacing: 0.3px;
  color: #f5f5f3;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.xt-text-imgdesc {
  padding: 20px 14px;
  background: linear-gradient(180deg, #1c1c20, #19191d);
  border: 1px solid rgba(201,168,106,0.2);
